const $in = $input.first().json;

const h = $in.headers || {};
const ip = String(h['x-real-ip'] || String(h['x-forwarded-for'] || '').split(',')[0] || 'unknown').trim();
const store = $getWorkflowStaticData('global');
const now = Date.now();
store.hits = Object.fromEntries(Object.entries(store.hits || {}).map(([k, v]) => [k, v.filter(t => now - t < 3600e3)]).filter(([, v]) => v.length));
const mine = store.hits[ip] || [];
if (mine.length >= 3000) return [{ json: { ok: false, status: 429, body: { success: false, message: 'Too many attempts from this network. Please try again in an hour.' } } }];
const count = () => { store.hits[ip] = [...mine, now]; };

// Automatic refreshes share one copy for 5 seconds so a crowd watching doesn't each hit the database.
// A page load or manual refresh sends fresh=1 and always reads the latest score (still rate limited).
const cache = $getWorkflowStaticData('global');
const key = 'm:' + String(($in.query || {}).slug || '') + ':' + String(($in.query || {}).id || '');
const hit = (cache.c || {})[key];
if (hit && Date.now() - hit.at < 5000 && String(($in.query || {}).fresh || '') !== '1') return [{ json: { ok: false, status: 200, body: hit.body } }];

const q = $in.query || {};
const slug = String(q.slug || '').toLowerCase(), id = Number(q.id);
if (!/^[a-z0-9-]{2,40}$/.test(slug) || !(Number.isInteger(id) && id > 0)) return [{ json: { ok: false, status: 404, body: { success: false, message: 'Match not found.' } } }];
count();
return [{ json: { ok: true, phone: '', id, slug, light: false, _q: { slug, id } } }];

const $in = $input.first().json;

const m = $in;
if (!m.id || !(Number(m.published) === 1 || Number(m.is_owner) === 1 || Number(m.can_score) === 1)) return [{ json: { ok: false, status: 404, body: { success: false, message: "Match not found." } } }];
return [{ json: { ok: true, ...m } }];

const b2 = $('Authorize B2').isExecuted ? $('Authorize B2').first().json : {};
const dl = b2?.apiInfo?.storageApi?.downloadUrl;
const tokenOf = node => { try { return $(node).isExecuted ? $(node).first().json.authorizationToken : null; } catch { return null; } };
const signWith = (key, node) => { const t = tokenOf(node); return key && dl && t ? `${dl}/file/mypaltan-profile-photos/${key.split('/').map(encodeURIComponent).join('/')}?Authorization=${t}` : null; };
const parseJ = v => { if (v === null || v === undefined) return null; if (typeof v === 'object') return v; try { return JSON.parse(v); } catch { return null; } };

const m = $('Check Found').first().json, r = $('Check Request').first().json;
const canScore = Number(m.can_score) === 1;
const lockedBy = m.scorer_user_id && Number(m.scorer_idle) < 180 && Number(m.scorer_user_id) !== Number(m.viewer_id) ? (m.scorer_name || 'Someone') : null;
const team = (id, name, short, logo, squad) => id ? { entry_id: id, name, short, logo_url: signWith(logo, 'Team Link'),
  squad: r.light ? undefined : (parseJ(squad) || []).sort((a, b) => String(a.name).localeCompare(String(b.name))) } : null;
const body = { success: true, match: {
  id: m.id, tournament_code: m.code, tournament_name: m.tname, sport: m.sport, division: m.division, format: m.format, match_rules: parseJ(m.match_rules) || {},
  stage: m.stage, label: m.label, group_no: m.group_no, round_no: m.round_no, match_no: m.match_no, pitch: m.pitch, scheduled_at: m.scheduled_at,
  status: m.status, toss_winner_entry_id: m.toss_winner_entry_id, toss_decision: m.toss_decision, result_text: m.result_text, winner_entry_id: m.winner_entry_id,
  home: team(m.home_entry_id, m.home_name, m.home_short, m.home_logo, m.home_squad), away: team(m.away_entry_id, m.away_name, m.away_short, m.away_logo, m.away_squad),
  lineups: r.light ? undefined : (parseJ(m.lineups) || []).map(p => ({ ...p, captain: !!Number(p.captain), keeper: !!Number(p.keeper) })),
  live: parseJ(m.live), event_count: Number(m.event_count || 0),
  is_owner: Number(m.is_owner) === 1, can_score: canScore, scoring_locked_by: lockedBy,
  events: canScore && !r.light ? (parseJ(m.events) || []).sort((a, b) => a.seq - b.seq).map(e => ({ client_id: e.client_id, type: e.type, data: parseJ(e.data) || {} })) : undefined,
} };
return [{ json: { status: 200, body } }];

const out = JSON.parse(JSON.stringify($input.first().json));

// Children's names on public pages: first name + last initial ("Aarav Shah" → "Aarav S.").
const short = n => { const w = String(n || '').trim().split(/\s+/).filter(Boolean); return w.length < 2 ? (w[0] || '') : `${w[0]} ${w[w.length - 1][0].toUpperCase()}.`; };
if (out.status === 200 && out.body && out.body.success) {
  // The match endpoint wraps its data in body.match.
  const b = out.body.match || out.body;
  for (const k of ['is_owner', 'can_score', 'scoring_locked_by', 'events', 'scorer_name', 'scorer_idle', 'scorer']) delete b[k];
  // Every full name in this match → "First L.", including inside timeline texts like "GOAL · Aarav Shah".
  const names = new Map();
  const add = n => { if (n && String(n).trim().includes(' ')) names.set(String(n).trim(), short(n)); };
  for (const side of [b.home, b.away]) for (const p of (side && side.squad) || []) add(p.name);
  for (const p of b.lineups || []) add(p.name);
  const live = b.live && typeof b.live === 'object' ? b.live : null;
  for (const p of (live && live.player_stats) || []) add(p.name);
  if (live && live.potm) add(live.potm.name);
  // Cricket scorecard: batters, bowlers, wickets, commentary and the current batters and bowler.
  const cur = live && live.current;
  for (const inn of (live && live.innings) || []) {
    for (const p of [...(inn.batting || []), ...(inn.bowling || []), ...(inn.fall_of_wickets || [])]) add(p.name);
    for (const n of inn.yet_to_bat || []) add(n);
  }
  for (const c of (live && live.commentary) || []) { add(c.batter); add(c.bowler); }
  if (cur) for (const p of [cur.striker, cur.non_striker, cur.bowler]) if (p) add(p.name);
  const fix = s => { if (typeof s !== 'string') return s; let t = s; for (const [f, sh] of names) t = t.split(f).join(sh); return t; };
  for (const side of [b.home, b.away]) if (side && side.squad) side.squad = side.squad.map(p => ({ member_id: p.member_id, name: short(p.name), jersey_number: p.jersey_number ?? null }));
  if (b.lineups) b.lineups = b.lineups.map(p => ({ ...p, name: short(p.name), user_id: undefined }));
  if (live) {
    for (const e of live.timeline || []) { if (e.player) e.player = short(e.player); if (e.assist) e.assist = short(e.assist); e.text = fix(e.text); }
    for (const p of live.player_stats || []) p.name = short(p.name);
    if (live.potm) live.potm.name = short(live.potm.name);
    for (const inn of live.innings || []) {
      for (const p of inn.batting || []) { p.name = short(p.name); p.how_out = fix(p.how_out); }
      for (const p of [...(inn.bowling || []), ...(inn.fall_of_wickets || [])]) p.name = short(p.name);
      inn.yet_to_bat = (inn.yet_to_bat || []).map(short);
    }
    for (const c of live.commentary || []) { c.batter = short(c.batter); c.bowler = short(c.bowler); c.text = fix(c.text); }
    if (cur) for (const p of [cur.striker, cur.non_striker, cur.bowler]) if (p) p.name = short(p.name);
    live.result = fix(live.result);
  }
  b.result_text = fix(b.result_text);
}

const cache = $getWorkflowStaticData('global');
const now = Date.now();
cache.c = Object.fromEntries(Object.entries(cache.c || {}).filter(([, v]) => now - v.at < 60000));
if (out.status === 200 && out.body && out.body.success) cache.c['m:' + String(($('Check Request').first().json._q || {}).slug || '') + ':' + String(($('Check Request').first().json._q || {}).id || '')] = { at: now, body: out.body };
return [{ json: out }];
